package com.bank.netting;

import java.util.*;
import java.util.logging.*;

public class ThreeSumDemo {
    private static final Logger log = Logger.getLogger(ThreeSumDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        NettingService svc = new NettingService();

        // Signed ledger adjustments (in thousands)
        int[] adj = {-4, -1, -1, 0, 1, 2, 2};
        List<List<Integer>> trios = svc.findZeroTriplets(adj);
        log.info(() -> "Zero-summing triplets: " + trios);
    }
}

