class NettingService {
    private static final Logger log = Logger.getLogger(NettingService.class.getName());

    // Sort + fix one + two pointers. O(n^2) time, O(1) extra space.
    List<List<Integer>> findZeroTriplets(int[] a) {
        Arrays.sort(a);
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < a.length - 2; i++) {
            if (i > 0 && a[i] == a[i - 1]) continue; // skip duplicate first element
            if (a[i] > 0) break;                     // no zero-sum possible beyond this
            int left = i + 1, right = a.length - 1;
            while (left < right) {
                int sum = a[i] + a[left] + a[right];
                if (sum == 0) {
                    result.add(List.of(a[i], a[left], a[right]));
                    while (left < right && a[left] == a[left + 1]) left++;  // skip dup left
                    while (left < right && a[right] == a[right - 1]) right--; // skip dup right
                    left++;
                    right--;
                } else if (sum < 0) {
                    left++;
                } else {
                    right--;
                }
            }
        }
        log.info(() -> "Found " + result.size() + " unique triplets");
        return result;
    }
}

